def transform(grid):
    """Move each 4 one cell downward toward the horizontal 2 barrier; preserve 4s below it."""
    h, w = len(grid), len(grid[0])
    wall = next((r for r, row in enumerate(grid) if row and all(v == 2 for v in row)), None)
    if wall is None:
        return [row[:] for row in grid]
    out = [[2 if v == 2 else 0 for v in row] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 4:
                continue
            if r > wall:
                out[r][c] = 4
            elif r + 1 < wall:
                out[r + 1][c] = 4
            # On the barrier approach, the 4 disappears if it is adjacent;
            # otherwise it advances one cell.
    return out
